fn v3_fall_back_to_passive(&mut self, version, rnd, player, data, debug)

// handler.rs:417 - v3 게이트
if version < 2 { return; }

let game = data.cache.game;   // &dyn AbstractGame (data+0x0 -> +0x0 데이터ptr, +0x8 vtable)

// handler.rs:421 - 데스매치 모드는 이 폴백을 아예 안 탄다
if game.mode()/*vt+0x40*/.tag == 2 /*GameMode::DeathMatch*/ { return; }

// handler.rs:424~427 - 후보 플랜 만들기
let mut plan: BigPlan =
  if game.mode().tag == 1 /*GameMode::SingleLane*/ {
     // handler.rs:425 - 힙할당 없는 고정 플랜 (BigPlan 태그 4)
     BigPlan::SinglePlanLine(SinglePlanLine { chats: Vec::new(), in_recall: false, line: LineType::Mid })
  } else {
     // handler.rs:427
     self.passive_plan(version, rnd, player, data, debug)
  };

// handler.rs:429 - rule_scope::plan_allowed(data.context, &plan) 이 통째로 인라인됨
//   plan_allowed(rule_scope.rs:101) = goal_allowed(context, plan.goal())
let tut: TutorialType = data.context.tutorial;   // GameContext+0x38, 값역 0..=8
let ok = match plan.goal() {   // BigGoal 태그 i8, 값역 0..=6 (그 외는 unreachable)
   BigGoal::Line(l) /*0*/ =>              // rule_scope.rs:92 line_exists -> runner.rs:275 spawn_line_minion
       match l {
         LineType::Top(0)    => tut in {0,2,7,8},      // runner.rs:283 spawn_top_minion
         LineType::Mid(1)    => tut in {0,4,5,7,8},    // runner.rs:287 spawn_mid_minion
         LineType::Bottom(2) => tut in {0,1,3,5,7,8},  // runner.rs:291 spawn_bottom_minion
       },
   BigGoal::Jungle(1) => tut in {0,6,8},   // rule_scope.rs:95 -> TutorialType::player_count(runner.rs:295) 상수접힘
   BigGoal::Epic(2)   => tut in {0,7,8},   // rule_scope.rs:93 morgard_exists(46) -> spawn_epic(runner.rs:263)
   BigGoal::Serpen(3) => tut in {0,5,7,8}, // rule_scope.rs:94 serpen_exists(50) -> spawn_serpen(runner.rs:267)
   BigGoal::Nexus(4) | BigGoal::Battle(5) | BigGoal::Recall(6) => true,   // 무조건 허용
};
//   TutorialType: 0=None 1=First 2=TopSolo 3=Bottom 4=MidSolo 5=MidBottom 6=JungleOnly 7=Line 8=Total
//   일반 경기 = None(0) 이라 네 경로 모두 true -> 이 게이트는 사실상 튜토리얼에서만 실효

if !ok { drop(plan); return; }   // self 를 전혀 안 건드리고 종료 (IR 블록 %70)

// ---- 여기부터 실제 반영 (IR 블록 %71~%89) ----
let tick = game.tick();          // vt+0x28
// handler.rs:432 = self.mf_note_swap(29, tick)  (handler.rs:409~410 인라인)
self.mf_swap = (29u8, tick);     // self+0x1610 = 29, self+0x1618 = tick
// handler.rs:433
self.v3_lapse_passive_fallbacks += 1;   // self+0x1628
// handler.rs:434 - 구 self.plan 을 drop 하고 새 plan 을 memcpy 이동
//   (언와인드 대비로 %9 에 백업본을 떠 두고, drop 중 패닉이면 그 백업을 되돌린다)
self.plan = plan;                // self+0x5e8
// handler.rs:435
let sub = self.plan.sub_plan(version, rnd, player, data,
                             &self.data /*self+0x0, 248B*/,
                             &mut self.team_plan /*self+0xf8*/,
                             &self.positioning_score /*self+0x990, 2760B*/,
                             debug);
// handler.rs:436
self.sub_plan.merge(&sub);       // self+0x768
// handler.rs:437 return
